import { sql } from 'drizzle-orm';
import {
  type AnyPgColumn,
  boolean,
  check,
  index,
  integer,
  jsonb,
  text,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import {
  eventKinds,
  eventRegistrationConsents,
  eventRegistrationStatuses,
  eventStatuses,
  noticeCategories,
  noticeStatuses,
} from '@takhti/contracts';
import { baseColumns, branchIdColumn } from '../../kernel/base-columns';
