/* The tables of M39 · Notices, events and calendar. */

export const notices = defineTable(
  'notices',
  { module: 'M39', scope: 'org' },
  {
    ...baseColumns,
    title: text().notNull(),
    titleUr: text(),
    /** rich text */
    body: text().notNull(),
    bodyUr: text(),
    category: enumText(noticeCategories).notNull().default('general'),
    /** `{ kinds: (guardians \ | students \ | staff)[], branchIds: [], gradeIds?: [], sectionIds?: [], roleKeys?: [] }` */
    audience: jsonb().notNull(),
    /** copied from the audience, for scoping */
    branchIds: uuid().array().notNull(),
    /** empty means on approval */
    publishAt: timestamptz(),
    expiresAt: timestamptz(),
    isPinned: boolean().notNull().default(false),
    needsAcknowledgement: boolean().notNull().default(false),
    /** send through the messaging hub as well as the board */
    alsoMessage: boolean().notNull().default(true),
    status: enumText(noticeStatuses).notNull().default('draft'),
    publishedAt: timestamptz(),
    approvalRequestId: uuid().references((): AnyPgColumn => approvalRequests.id),
    createdBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [index('notices_status_published_at_idx').on(t.orgId, t.status, t.publishedAt)],
);

/** Created when a notice is published: one row per person it is for. */
export const noticeRecipients = defineTable(
  'notice_recipients',
  { module: 'M39', scope: 'org', self: 'userId' },
  {
    ...baseColumns,
    noticeId: uuid()
      .references((): AnyPgColumn => notices.id)
      .notNull(),
    userId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    /** the child it concerns, for a guardian */
    studentId: uuid().references((): AnyPgColumn => students.id),
    readAt: timestamptz(),
    acknowledgedAt: timestamptz(),
  },
  (t) => [
    uniqueIndex('notice_recipients_notice_user_uq').on(t.noticeId, t.userId).where(live(t)),
    index('notice_recipients_user_read_at_idx').on(t.userId, t.readAt),
  ],
);

export const events = defineTable(
  'events',
  { module: 'M39', scope: 'org' },
  {
    ...baseColumns,
    title: text().notNull(),
    titleUr: text(),
    /** rich text */
    description: text(),
    kind: enumText(eventKinds).notNull(),
    startsAt: timestamptz().notNull(),
    endsAt: timestamptz().notNull(),
    isAllDay: boolean().notNull().default(false),
    branchIds: uuid().array().notNull(),
    venue: text(),
    roomId: uuid().references((): AnyPgColumn => rooms.id),
    /** the same shape as a notice's */
    audience: jsonb().notNull(),
    organiserStaffId: uuid().references((): AnyPgColumn => staff.id),
    needsRegistration: boolean().notNull().default(false),
    /** a guardian must agree, as for a trip */
    needsConsent: boolean().notNull().default(false),
    capacity: integer(),
    fee: paisa().notNull().default(0),
    /** required when `fee` is above zero */
    feeHeadId: uuid().references((): AnyPgColumn => feeHeads.id),
    registrationClosesAt: timestamptz(),
    showOnWebsite: boolean().notNull().default(false),
    status: enumText(eventStatuses).notNull().default('draft'),
  },
  (t) => [
    check('events_ends_at_from', sql`${t.endsAt} >= ${t.startsAt}`),
    nonNegative('events', t.fee),
    check('events_fee_head_id_needed', sql`${t.fee} = 0 or ${t.feeHeadId} is not null`),
    index('events_starts_at_idx').on(t.orgId, t.startsAt),
  ],
);

export const eventRegistrations = defineTable(
  'event_registrations',
  {
    module: 'M39',
    scope: 'branch',
    family: 'studentId',
    familyRule: {
      read: true,
      insert: { status: ['registered', 'waitlisted'] },
      update: { status: ['registered', 'waitlisted'] },
    },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    eventId: uuid()
      .references((): AnyPgColumn => events.id)
      .notNull(),
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    status: enumText(eventRegistrationStatuses).notNull().default('registered'),
    consent: enumText(eventRegistrationConsents).notNull().default('not_needed'),
    consentBy: uuid().references((): AnyPgColumn => profiles.id),
    consentAt: timestamptz(),
    feeVoucherId: uuid().references((): AnyPgColumn => feeVouchers.id),
    /** for a trip */
    emergencyPhone: text(),
    note: text(),
    registeredBy: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
  },
  (t) => [
    uniqueIndex('event_registrations_event_student_uq').on(t.eventId, t.studentId).where(live(t)),
  ],
);

export const eventStaff = defineTable(
  'event_staff',
  { module: 'M39', scope: 'branch' },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    eventId: uuid()
      .references((): AnyPgColumn => events.id)
      .notNull(),
    staffId: uuid()
      .references((): AnyPgColumn => staff.id)
      .notNull(),
    /** "Bus 2 supervisor" */
    duty: text(),
  },
  (t) => [uniqueIndex('event_staff_event_staff_uq').on(t.eventId, t.staffId).where(live(t))],
);

/** A private link that lets a person's own calendar app subscribe. */
export const calendarFeeds = defineTable(
  'calendar_feeds',
  { module: 'M39', scope: 'org', self: 'userId' },
  {
    ...baseColumns,
    userId: uuid()
      .references((): AnyPgColumn => profiles.id)
      .notNull(),
    tokenHash: text().notNull(),
    lastUsedAt: timestamptz(),
    revokedAt: timestamptz(),
  },
  (t) => [uniqueIndex('calendar_feeds_token_hash_uq').on(t.tokenHash)],
);
